.isbn.nl/1172768/de-obeliskpoort.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1172768/de-obeliskpoort.html","sha256":"0c9e5743c458cedd05b6a872c4aa1ffc23005c9987f0be26ba174d1707cc5daa","checkedAt":"2026-11-01T13:58:45.529Z","fact":"Paperback ISBN 9789024580453 verschijningsdatum 04/04/2019 NUR 334 Fantasy imprint Luitingh Sijthoff Fantasy uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"N.K. Jemisin","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789024555383","key":{"edition_id":977200028},"before":null,"after":{"edition_id":977200028,"work_id":977100014,"bound_author_id":8800015,"bound_title":"Een kroon van zwaarden","bound_language":"dut","bound_isbn13":"9789024555383","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000214403_Een_kroon_van_zwaarden_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1463834/het-rad-des-tijds-7-een-kroon-van-zwaarden-pod.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1463834/het-rad-des-tijds-7-een-kroon-van-zwaarden-pod.html","sha256":"f1dc64b1f26cd5ad1f4d51c89901caddf036deeed4bfd688042d4310821b7f52","checkedAt":"2026-11-01T13:59:03.088Z","fact":"Hardback ISBN 9789024555383 verschijningsdatum 13/07/2006 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000214403_Een_kroon_van_zwaarden_0_0.jpg","sha256":"e036970ec1d624995f58d116582f79c2096ff6fb25be6f52722bce49ceb46c34","bytes":96912,"checkedAt":"2026-11-01T14:19:34.204Z","fact":"Exact ISBN block image + human visual title/author review, sheet2"}]}},{"relation":"catalog_work_descriptions","ref":"description:2539","key":{"work_id":977100014,"language":"nl"},"before":null,"after":{"work_id":977100014,"language":"nl","bound_author_id":8800015,"text":"Terwijl de Laatste Slag dichterbij komt, raken de tegenstanders van de Duistere steeds verder over verschillende gebieden verspreid. Rhand Altor breidt zijn macht uit en Egwene leidt haar aanhangers naar het noorden. Elders zoeken Elayne, Aviendha, Nynaeve en Mart naar de Schaal der Winden. Hun ondernemingen spelen zich af tegenover een vijand die oude dienaren in nieuwe gedaanten opnieuw inzet en daarmee herkenning en vertrouwen bemoeilijkt.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1463834/het-rad-des-tijds-7-een-kroon-van-zwaarden-pod.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1463834/het-rad-des-tijds-7-een-kroon-van-zwaarden-pod.html","sha256":"f1dc64b1f26cd5ad1f4d51c89901caddf036deeed4bfd688042d4310821b7f52","checkedAt":"2026-11-01T13:59:03.088Z","fact":"Hardback ISBN 9789024555383 verschijningsdatum 13/07/2006 NUR 334 Fantasy imprint Luitingh uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Robert Jordan","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"catalog_edition_metadata","ref":"metadata:9789400517905","key":{"edition_id":977200029},"before":null,"after":{"edition_id":977200029,"work_id":977100015,"bound_author_id":91021002,"bound_title":"Winterberg","bound_language":"nld","bound_isbn13":"9789400517905","format":"paperback","cover_url":